    /**
     * Minimal in-memory {@link PtyProcess}: records every byte block written to its
     * output stream and can be switched to fail writes on demand.
     */
    private static final class FakePtyProcess extends PtyProcess {

        private final List<byte[]> writes = Collections.synchronizedList(new ArrayList<>());
        private final InputStream emptyInput = new ByteArrayInputStream(new byte[0]);
        private final ByteArrayOutputStream discard = new ByteArrayOutputStream();
        private volatile boolean failWrites;

        private final OutputStream output = new OutputStream() {
            @Override
            public void write(int b) throws IOException {
                write(new byte[]{(byte) b}, 0, 1);
            }

            @Override
            public void write(byte[] b, int off, int len) throws IOException {
                if (failWrites) {
                    throw new IOException("simulated PTY failure");
                }
                writes.add(Arrays.copyOfRange(b, off, off + len));
                discard.write(b, off, len);
            }
        };

        List<String> writtenStrings() {
            List<byte[]> snapshot;
            synchronized (writes) {
                snapshot = new ArrayList<>(writes);
            }
            List<String> result = new ArrayList<>(snapshot.size());
            for (byte[] bytes : snapshot) {
                result.add(new String(bytes, StandardCharsets.UTF_8));
            }
            return result;
        }

        @Override
        public OutputStream getOutputStream() {
            return output;
        }

        @Override
        public InputStream getInputStream() {
            return emptyInput;
        }

        @Override
        public InputStream getErrorStream() {
            return new ByteArrayInputStream(new byte[0]);
        }

        @Override
        public int waitFor() {
            return 0;
        }

        @Override
        public int exitValue() {
            return 0;
        }

        @Override
        public void destroy() {
            // nothing to release
        }

        @Override
        public void setWinSize(WinSize winSize) {
            // not used by the tests
        }

        @Override
        public WinSize getWinSize() throws IOException {
            return new WinSize(80, 24);
        }
    }

    @SuppressWarnings("unused")
    private static void assertWrites(List<String> expected, List<String> actual) {
        assertTrue(actual.size() == expected.size(),
                () -> "expected " + expected + " but got " + actual);
    }
}
