        }

        String writes() {
            synchronized (writeLock) {
                return captured.toString();
            }
        }

        boolean awaitFirstWrite(long timeoutMs) throws InterruptedException {
            return firstWrite.await(timeoutMs, TimeUnit.MILLISECONDS);
        }

