/**
 * Behavioural tests for ClaudeSessionController's model-discovery workflow.
 *
 * <p>The PTY boundary is represented by a tiny in-memory PtyProcess: it captures
 * every byte the controller writes and never starts an external process.  Screen
 * content is supplied through the controller's normal screen-lines supplier.
 */
@Timeout(15)
class ClaudeSessionControllerDiscoverModelsTests {

    private static final String DISCOVERY_THREAD_NAME = "claude-model-discovery";
    private static final List<String> USABLE_MODEL_SCREEN = List.of(
            "────────────────",
            "❯ claude-opus-4-6",
            "────────────────",
            "  claude-sonnet-4-6");

    @AfterEach
    void stopAnyDiscoveryThread() throws InterruptedException {
        for (Thread thread : Thread.getAllStackTraces().keySet()) {
            if (DISCOVERY_THREAD_NAME.equals(thread.getName()) && thread.isAlive()) {
                thread.interrupt();
                thread.join(3_000);
            }
        }
    }

    @Test
    void discoversModelsThroughPollScreenStateAndAppendsProfileModels() throws Exception {
        ClaudeSessionModel model = new ClaudeSessionModel();
        CapturingPtyProcess process = new CapturingPtyProcess();
        ClaudeSessionController controller = controllerWithConnector(model, USABLE_MODEL_SCREEN, process);
        setField(controller, "customModelIds", List.of("custom/model-a", "custom/model-b"));
        model.setLifecycle(SessionLifecycle.READY);

        controller.pollScreenState();

        awaitLifecycle(model, SessionLifecycle.READY, 5_000);
        assertEquals(List.of("claude-opus-4-6", "claude-sonnet-4-6",
                        "custom/model-a", "custom/model-b"),
                model.getAvailableModels());
        assertEquals(0, model.getSelectedModelIndex(),
                "the legacy cursor line should identify the current model");
        assertEquals(2, getField(controller, "standardModelCount"),
                "only the CLI-discovered models count as standard models");
        assertFalse((Boolean) getField(controller, "modelComboPopulated"),
                "discovery is marked populate-before-work and should be finalised");
        assertFalse((Boolean) getField(controller, "modelDiscoveryInProgress"));
        assertEquals("/model\u001b\r\u001b", process.writes(),
                "discovery should open /model, execute it, and dismiss the menu with Esc");
    }

    @Test
    void fallsBackToDetectedChoiceMenuWhenModelParserFindsNoModels() throws Exception {
        ClaudeSessionModel model = new ClaudeSessionModel();
        CapturingPtyProcess process = new CapturingPtyProcess();
        List<String> screen = List.of(
                "Choose a model",
                "❯ 1. Alpha",
                "  2. Beta");
        ClaudeSessionController controller = controllerWithConnector(model, screen, process);

        controller.discoverModels();

        awaitLifecycle(model, SessionLifecycle.READY, 5_000);
        assertEquals(List.of("Alpha", "Beta"), model.getAvailableModels());
        assertEquals(-1, model.getSelectedModelIndex());
        assertEquals("/model\u001b\r\u001b", process.writes());
    }

    @Test
    void replacesTruncatedCurrentlyEntryWithModelFromPtyHintLine() throws Exception {
        ClaudeSessionModel model = new ClaudeSessionModel();
        CapturingPtyProcess process = new CapturingPtyProcess();
        List<String> screen = List.of(
                "Choose a model",
                "❯ 1. Default  Use the default model (currently anthropic/cl",
                "  2. Opus  Opus 4.6 · Most capable");
        ClaudeSessionController controller = controllerWithConnector(model, screen, process);
        controller.simulatePtyLine("❯ /model  … (currently anthropic/claude-sonnet-4.6)");

        controller.discoverModels();

        awaitLifecycle(model, SessionLifecycle.READY, 5_000);
        assertEquals(List.of("anthropic/claude-sonnet-4.6", "Opus 4.6"),
                model.getAvailableModels(),
                "a terminal-width-truncated (currently ...) label must be repaired from the hint line");
    }

    @Test
    void enumeratesScrollableMenuAndIncludesTheWholeList() throws Exception {
        ClaudeSessionModel model = new ClaudeSessionModel();
        CapturingPtyProcess process = new CapturingPtyProcess();
        List<String> screen = List.of(
                "Choose a model",
                "❯ 1. Alpha",
                "  2. Beta",
                "↓ 3. Gamma");
        ClaudeSessionController controller = controllerWithConnector(model, screen, process);

        controller.discoverModels();

        awaitLifecycle(model, SessionLifecycle.READY, 5_000);
        assertEquals(List.of("Alpha", "Beta", "Gamma"), model.getAvailableModels());
        assertEquals("/model\u001b\r\u001b[B\u001b", process.writes(),
                "scrollable menus must be walked with arrow-down before dismissal");
    }

    @Test
    void doesNothingWithoutAConnector() throws Exception {
        ClaudeSessionModel model = new ClaudeSessionModel();
        ClaudeSessionController controller = new ClaudeSessionController(model, () -> USABLE_MODEL_SCREEN);

        controller.discoverModels();

        assertEquals(SessionLifecycle.STARTING, model.getLifecycle());
        assertEquals(List.of(), model.getAvailableModels());
        assertEquals(0, getField(controller, "modelDiscoveryAttempts"));
        assertFalse(hasLiveDiscoveryThread());
    }

    @Test
    void doesNothingWhenTheModelComboIsAlreadyPopulated() throws Exception {
        ClaudeSessionModel model = new ClaudeSessionModel();
        CapturingPtyProcess process = new CapturingPtyProcess();
        ClaudeSessionController controller = controllerWithConnector(model, USABLE_MODEL_SCREEN, process);
        setField(controller, "modelComboPopulated", true);

        controller.discoverModels();

        assertEquals("", process.writes());
        assertEquals(SessionLifecycle.STARTING, model.getLifecycle());
        assertFalse(hasLiveDiscoveryThread());
    }

    @Test
    void doesNothingWhenAnotherDiscoveryIsAlreadyInProgress() throws Exception {
        ClaudeSessionModel model = new ClaudeSessionModel();
        CapturingPtyProcess process = new CapturingPtyProcess();
        ClaudeSessionController controller = controllerWithConnector(model, USABLE_MODEL_SCREEN, process);
        setField(controller, "modelDiscoveryInProgress", true);

        controller.discoverModels();

        assertEquals("", process.writes());
        assertEquals(SessionLifecycle.STARTING, model.getLifecycle());
        assertFalse(hasLiveDiscoveryThread());
    }

    @Test
    void doesNothingAfterTheAttemptBudgetIsExhausted() throws Exception {
        ClaudeSessionModel model = new ClaudeSessionModel();
        CapturingPtyProcess process = new CapturingPtyProcess();
        ClaudeSessionController controller = controllerWithConnector(model, USABLE_MODEL_SCREEN, process);
        setField(controller, "modelDiscoveryAttempts", 1);

        controller.discoverModels();

        assertEquals("", process.writes());
        assertEquals(SessionLifecycle.STARTING, model.getLifecycle());
        assertEquals(List.of(), model.getAvailableModels());
        assertFalse(hasLiveDiscoveryThread());
    }

    @Test
    void failedWriteResetsDiscoveryStateAndReturnsToReady() throws Exception {
        ClaudeSessionModel model = new ClaudeSessionModel();
        FailingPtyProcess process = new FailingPtyProcess();
        ClaudeSessionController controller = controllerWithConnector(model, USABLE_MODEL_SCREEN, process);

        controller.discoverModels();

        assertEquals(SessionLifecycle.WORKING, model.getLifecycle(),
                "starting discovery immediately marks the session WORKING");
        awaitLifecycle(model, SessionLifecycle.READY, 4_000);
        assertTrue(process.writeAttempts() > 0, "the discovery command should have been attempted");
        assertEquals(List.of(), model.getAvailableModels());
        assertFalse((Boolean) getField(controller, "modelComboPopulated"));
        assertFalse((Boolean) getField(controller, "modelDiscoveryInProgress"));
        assertEquals(1, getField(controller, "modelDiscoveryAttempts"));
    }

    @Test
    void interruptedDiscoveryResetsStateAndReturnsToReady() throws Exception {
        ClaudeSessionModel model = new ClaudeSessionModel();
        CapturingPtyProcess process = new CapturingPtyProcess();
        ClaudeSessionController controller = controllerWithConnector(model, USABLE_MODEL_SCREEN, process);

        controller.discoverModels();
        Thread discovery = awaitDiscoveryThread(2_000);
        assertNotNull(discovery);
        assertTrue(process.awaitFirstWrite(2_000), "discovery should start by writing /model");
        discovery.interrupt();

        awaitLifecycle(model, SessionLifecycle.READY, 4_000);
        assertEquals(List.of(), model.getAvailableModels());
        assertEquals("/model", process.writes(),
                "interrupting during the post-/model pause must abandon the remaining write sequence");
        assertFalse((Boolean) getField(controller, "modelComboPopulated"));
        assertFalse((Boolean) getField(controller, "modelDiscoveryInProgress"));
    }

    @Test
    void emptyDiscoveryKeepsTheFailedAttemptAndDoesNotRetry() throws Exception {
        ClaudeSessionModel model = new ClaudeSessionModel();
        CapturingPtyProcess process = new CapturingPtyProcess();
        ClaudeSessionController controller = controllerWithConnector(model, List.of(), process);

        controller.discoverModels();

        assertEquals(SessionLifecycle.WORKING, model.getLifecycle());
        awaitLifecycle(model, SessionLifecycle.READY, 10_000);
        assertEquals(List.of(), model.getAvailableModels());
        assertEquals(1, getField(controller, "modelDiscoveryAttempts"));
        assertFalse((Boolean) getField(controller, "modelComboPopulated"),
                "an empty result should allow retry if the attempt budget itself allowed it");
        String writesAfterFirstAttempt = process.writes();
        assertEquals("/model\u001b\r\u001b", writesAfterFirstAttempt);

        controller.discoverModels();

        assertEquals(writesAfterFirstAttempt, process.writes(),
                "the single-attempt budget must prevent an immediate second /model command");
        assertFalse(hasLiveDiscoveryThread());
    }

    // ---------------------------------------------------------------------
    // Test helpers and fakes
    // ---------------------------------------------------------------------

    private static ClaudeSessionController controllerWithConnector(
            ClaudeSessionModel model, List<String> screenLines, PtyProcess process) throws Exception {
        return controllerWithConnector(model, () -> screenLines, process);
    }

    private static ClaudeSessionController controllerWithConnector(
            ClaudeSessionModel model, Supplier<List<String>> screenLines, PtyProcess process) throws Exception {
        ClaudeSessionController controller = new ClaudeSessionController(model, screenLines);
        setField(controller, "connector", new PtyTtyConnector(process));
        return controller;
    }

    private static void awaitLifecycle(ClaudeSessionModel model, SessionLifecycle expected, long timeoutMs)
            throws InterruptedException {
        awaitTrue("lifecycle to become " + expected, timeoutMs,
                () -> model.getLifecycle() == expected);
    }

    private static void awaitTrue(String description, long timeoutMs, BooleanSupplier condition)
            throws InterruptedException {
        long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(timeoutMs);
        while (System.nanoTime() < deadline) {
            if (condition.getAsBoolean()) return;
            Thread.sleep(20);
        }
        if (!condition.getAsBoolean()) {
            fail("Timed out waiting for " + description);
        }
    }

    private static Thread awaitDiscoveryThread(long timeoutMs) throws InterruptedException {
        long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(timeoutMs);
        while (System.nanoTime() < deadline) {
            for (Thread thread : Thread.getAllStackTraces().keySet()) {
                if (DISCOVERY_THREAD_NAME.equals(thread.getName()) && thread.isAlive()) {
                    return thread;
                }
            }
            Thread.sleep(10);
        }
        return null;
    }

    private static boolean hasLiveDiscoveryThread() {
        for (Thread thread : Thread.getAllStackTraces().keySet()) {
            if (DISCOVERY_THREAD_NAME.equals(thread.getName()) && thread.isAlive()) {
                return true;
            }
        }
        return false;
    }

    private static void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @SuppressWarnings("unchecked")
    private static <T> T getField(Object target, String fieldName) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        return (T) field.get(target);
    }

    /** A PtyProcess whose stdin is empty and whose stdout captures controller writes. */
    private static class CapturingPtyProcess extends PtyProcess {
        private final Object writeLock = new Object();
        private final StringBuilder captured = new StringBuilder();
        private final CountDownLatch firstWrite = new CountDownLatch(1);
        private volatile WinSize winSize = new WinSize(120, 40);
        private volatile boolean destroyed;

        private final OutputStream output = new OutputStream() {
            @Override
            public void write(int b) {
                append(new byte[]{(byte) b}, 0, 1);
            }

            @Override
            public void write(byte[] b, int off, int len) {
                append(b, off, len);
            }
        };

        private void append(byte[] bytes, int offset, int length) {
            synchronized (writeLock) {
                captured.append(new String(bytes, offset, length, StandardCharsets.UTF_8));
            }
            firstWrite.countDown();
        }

        String writes() {
            synchronized (writeLock) {
                return captured.toString();
            }
        }

        boolean awaitFirstWrite(long timeoutMs) throws InterruptedException {
            return firstWrite.await(timeoutMs, TimeUnit.MILLISECONDS);
        }

        @Override public OutputStream getOutputStream() { return output; }
        @Override public InputStream getInputStream() { return new ByteArrayInputStream(new byte[0]); }
        @Override public InputStream getErrorStream() { return new ByteArrayInputStream(new byte[0]); }
        @Override public int waitFor() { return 0; }
        @Override public int exitValue() { return 0; }
        @Override public void destroy() { destroyed = true; }
        @Override public void setWinSize(WinSize winSize) { this.winSize = winSize; }
        @Override public WinSize getWinSize() { return winSize; }
    }

    /** A PtyProcess whose output stream fails on the first controller write. */
    private static final class FailingPtyProcess extends PtyProcess {
        private int writeAttempts;
        private volatile WinSize winSize = new WinSize(120, 40);

        private final OutputStream output = new OutputStream() {
            @Override
            public void write(int b) throws IOException {
                writeAttempts++;
                throw new IOException("simulated PTY write failure");
            }

            @Override
            public void write(byte[] b, int off, int len) throws IOException {
                writeAttempts++;
                throw new IOException("simulated PTY write failure");
            }
        };

        int writeAttempts() {
            return writeAttempts;
        }

        @Override public OutputStream getOutputStream() { return output; }
        @Override public InputStream getInputStream() { return new ByteArrayInputStream(new byte[0]); }
        @Override public InputStream getErrorStream() { return new ByteArrayInputStream(new byte[0]); }
        @Override public int waitFor() { return 0; }
        @Override public int exitValue() { return 0; }
        @Override public void destroy() { }
        @Override public void setWinSize(WinSize winSize) { this.winSize = winSize; }
        @Override public WinSize getWinSize() { return winSize; }
    }
}
