 * Behavioural tests for {@link StreamingState#processChunk(String)}: the OpenAI-SSE to
 * Anthropic-SSE streaming translation state machine.
 *
 * <p>Every assertion is made on the produced SSE text (event names plus the parsed JSON
 * payload of each {@code data:} line) and on the state accessors exposed by
 * {@code StreamingState}. No private helper is invoked directly.
 */
class AnthropicToOpenAITranslatorProcessChunkTests {

    private static final ObjectMapper JSON = new ObjectMapper();

    // ---------------------------------------------------------------------
    // SSE parsing helpers
    // ---------------------------------------------------------------------

    /** One parsed SSE frame: the {@code event:} name and the parsed {@code data:} JSON. */
    private record SseEvent(String name, JsonNode data) {

        String type() {
            return data.path("type").asText();
        }

        int index() {
            return data.path("index").asInt(-999);
        }
    }

    private static List<SseEvent> parse(String sse) {
        List<SseEvent> events = new ArrayList<>();
        if (sse == null || sse.isEmpty()) {
            return events;
        }
        for (String block : sse.split("\n\n")) {
            if (block.isBlank()) {
                continue;
            }
            String name = null;
            String data = null;
            for (String line : block.split("\n", -1)) {
                if (line.startsWith("event: ")) {
                    name = line.substring("event: ".length());
                } else if (line.startsWith("data: ")) {
                    data = line.substring("data: ".length());
                }
            }
            assertNotNull(name, "SSE frame without an event name: " + block);
            assertNotNull(data, "SSE frame without a data line: " + block);
            try {
                events.add(new SseEvent(name, JSON.readTree(data)));
            } catch (Exception e) {
                throw new AssertionError("SSE data line is not valid JSON: " + data, e);
            }
        }
        return events;
    }

    private static List<SseEvent> process(StreamingState state, String... dataLines) {
        List<SseEvent> events = new ArrayList<>();
        for (String line : dataLines) {
            events.addAll(parse(state.processChunk(line)));
        }
        return events;
    }

    private static List<String> names(List<SseEvent> events) {
        return events.stream().map(SseEvent::name).collect(Collectors.toList());
    }

    private static List<Integer> stopIndexes(List<SseEvent> events) {
        return events.stream()
                .filter(e -> "content_block_stop".equals(e.name()))
                .map(SseEvent::index)
                .collect(Collectors.toList());
    }

    private static List<SseEvent> named(List<SseEvent> events, String eventName) {
        return events.stream().filter(e -> eventName.equals(e.name())).collect(Collectors.toList());
    }

    private static SseEvent single(List<SseEvent> events, String eventName) {
        List<SseEvent> matching = named(events, eventName);
        assertEquals(1, matching.size(), "expected exactly one '" + eventName + "' event in " + names(events));
        return matching.get(0);
    }

    /** Delta-text fragments carried by {@code content_block_delta} frames of type {@code text_delta}. */
    private static String textDeltas(List<SseEvent> events, int blockIndex) {
        StringBuilder sb = new StringBuilder();
        for (SseEvent e : events) {
            if ("content_block_delta".equals(e.name())
                    && "text_delta".equals(e.data().path("delta").path("type").asText())
                    && e.index() == blockIndex) {
                sb.append(e.data().path("delta").path("text").asText());
            }
        }
        return sb.toString();
    }

    // ---------------------------------------------------------------------
    // Chunk builders (only the fields the target reads)
    // ---------------------------------------------------------------------

    private static String textChunk(String text) {
        return "{\"choices\":[{\"index\":0,\"delta\":{\"content\":\"" + text + "\"}}]}";
    }

    private static String textChunkWithFinish(String text, String finishReason) {
        return "{\"choices\":[{\"index\":0,\"delta\":{\"content\":\"" + text + "\"},"
                + "\"finish_reason\":\"" + finishReason + "\"}]}";
    }

    private static String reasoningChunk(String reasoning) {
        return "{\"choices\":[{\"index\":0,\"delta\":{\"reasoning_content\":\"" + reasoning + "\"}}]}";
    }

    private static String toolStartChunk(int index, String id, String name) {
        return "{\"choices\":[{\"index\":0,\"delta\":{\"tool_calls\":[{\"index\":" + index
                + ",\"id\":\"" + id + "\",\"type\":\"function\",\"function\":{\"name\":\"" + name
                + "\",\"arguments\":\"\"}}]}}]}";
    }

    private static String toolArgsChunk(int index, String argumentsJson) {
        return "{\"choices\":[{\"index\":0,\"delta\":{\"tool_calls\":[{\"index\":" + index
                + ",\"function\":{\"arguments\":" + JSON_STRING(argumentsJson) + "}}]}}]}";
    }

    private static String JSON_STRING(String raw) {
        try {
            return JSON.writeValueAsString(raw);
        } catch (Exception e) {
            throw new IllegalStateException(e);
        }
    }

    // =====================================================================
    // Invalid / non-JSON input
    // =====================================================================

    @Test
    @DisplayName("Non-JSON data lines are swallowed and leave the state untouched")
    void nonJsonDataLineProducesNothing() {
        StreamingState state = new StreamingState();

        assertEquals("", state.processChunk("not json at all"));
        assertEquals("", state.processChunk("{broken"));
        // "[DONE] " is not exactly "[DONE]", so it is treated as (invalid) JSON.
        assertEquals("", state.processChunk("[DONE] "));

        assertFalse(state.isMessageStarted(), "invalid JSON must not start a message");
        assertFalse(state.isDoneReceived(), "invalid JSON must not mark the stream as done");
        assertEquals(0, state.getInputTokens());
        assertEquals(0, state.getOutputTokens());
    }

    @Test
    @DisplayName("An empty data line is parsed as an empty chunk and starts the message")
    void emptyDataLineIsTreatedAsEmptyJsonChunk() {
        StreamingState state = new StreamingState();

        List<SseEvent> events = parse(state.processChunk(""));

        assertEquals(List.of("message_start", "ping"), names(events));
        assertTrue(state.isMessageStarted());
        assertEquals("msg_proxy", single(events, "message_start").data().path("message").path("id").asText());
    }

    @Test
    @DisplayName("The JSON literal null is a valid, empty chunk")
    void jsonNullLiteralStartsMessageWithoutContent() {
        StreamingState state = new StreamingState();

        List<SseEvent> events = parse(state.processChunk("null"));

        assertEquals(List.of("message_start", "ping"), names(events));
        assertEquals("", single(events, "message_start").data().path("message").path("model").asText());
        assertFalse(state.isDoneReceived());
    }

    // =====================================================================
    // First chunk: message_start + ping
    // =====================================================================

    @Test
    @DisplayName("First chunk emits message_start (with id/model) and ping before any content")
    void firstChunkEmitsMessageStartAndPing() {
        StreamingState state = new StreamingState();

        String out = state.processChunk("{\"id\":\"chatcmpl-42\",\"model\":\"gpt-4o-mini\","
                + "\"choices\":[{\"index\":0,\"delta\":{\"role\":\"assistant\",\"content\":\"hello\"}}]}");

        List<SseEvent> events = parse(out);
        assertEquals(List.of("message_start", "ping", "content_block_start", "content_block_delta"),
                names(events));
        assertEquals(List.of("message_start", "ping", "content_block_start", "content_block_delta"),
                events.stream().map(SseEvent::type).collect(Collectors.toList()));

        SseEvent messageStart = events.get(0);
        JsonNode message = messageStart.data().path("message");
        assertEquals("message", message.path("type").asText());
        assertEquals("assistant", message.path("role").asText());
        assertEquals("chatcmpl-42", message.path("id").asText());
        assertEquals("gpt-4o-mini", message.path("model").asText());
        assertTrue(message.path("content").isArray());
        assertEquals(0, message.path("content").size());
        assertTrue(message.path("stop_reason").isNull());
        assertTrue(message.path("stop_sequence").isNull());
        assertEquals(0, message.path("usage").path("input_tokens").asInt());
        assertEquals(0, message.path("usage").path("output_tokens").asInt());

        SseEvent ping = events.get(1);
        assertEquals("ping", ping.type());

        SseEvent blockStart = events.get(2);
        assertEquals(0, blockStart.index());
        assertEquals("text", blockStart.data().path("content_block").path("type").asText());
        assertEquals("", blockStart.data().path("content_block").path("text").asText());

        SseEvent delta = events.get(3);
        assertEquals(0, delta.index());
        assertEquals("text_delta", delta.data().path("delta").path("type").asText());
        assertEquals("hello", delta.data().path("delta").path("text").asText());

        assertTrue(state.isMessageStarted());
        assertFalse(state.isDoneReceived());
    }

    @Test
    @DisplayName("Missing or null id/model fall back to the documented defaults")
    void missingIdAndModelFallBackToDefaults() {
        StreamingState withoutFields = new StreamingState();
        List<SseEvent> first = parse(withoutFields.processChunk(textChunk("a")));
        JsonNode message = single(first, "message_start").data().path("message");
        assertEquals("msg_proxy", message.path("id").asText());
        assertEquals("", message.path("model").asText());
    }

    @Test
    @DisplayName("Null id/model fall back to the documented defaults")
    void nullIdAndModelFallBackToDefaults() {
        StreamingState state = new StreamingState();
        List<SseEvent> events = parse(state.processChunk(
                "{\"id\":null,\"model\":null,\"choices\":[{\"delta\":{\"content\":\"a\"}}]}"));
        JsonNode message = single(events, "message_start").data().path("message");
        assertEquals("msg_proxy", message.path("id").asText());
        assertEquals("", message.path("model").asText());
