    @Test
    @DisplayName("message_start and ping are emitted only for the first chunk")
    void messageStartEmittedOnlyOnce() {
        StreamingState state = new StreamingState();

        List<SseEvent> first = parse(state.processChunk(
                "{\"id\":\"first-id\",\"model\":\"first-model\",\"choices\":[{\"delta\":{\"content\":\"a\"}}]}"));
        List<SseEvent> second = parse(state.processChunk(
                "{\"id\":\"second-id\",\"model\":\"second-model\",\"choices\":[{\"delta\":{\"content\":\"b\"}}]}"));

        assertEquals(List.of("message_start", "ping", "content_block_start", "content_block_delta"),
                names(first));
        assertEquals(List.of("content_block_delta"), names(second));
        assertEquals("first-id",
                single(first, "message_start").data().path("message").path("id").asText());
        assertTrue(textDeltas(first, 0).equals("a") && textDeltas(second, 0).equals("b"),
                "each chunk's text must be forwarded to the same block");
    }

    // =====================================================================
    // Text streaming
    // =====================================================================

    @Test
    @DisplayName("Successive text fragments share one text block and one index")
    void textFragmentsShareOneTextBlock() {
        StreamingState state = new StreamingState();

        List<SseEvent> first = parse(state.processChunk(textChunk("Hel")));
        List<SseEvent> second = parse(state.processChunk(textChunk("lo ")));
        List<SseEvent> third = parse(state.processChunk(textChunk("world")));

        assertEquals(1, named(first, "content_block_start").size(), "text block must open exactly once");
        assertTrue(named(second, "content_block_start").isEmpty());
        assertTrue(named(third, "content_block_start").isEmpty());

        List<SseEvent> all = new ArrayList<>();
        all.addAll(first);
        all.addAll(second);
        all.addAll(third);
        assertEquals("Hello world", textDeltas(all, 0));
        assertEquals(3, named(all, "content_block_delta").size());
        assertTrue(named(all, "content_block_delta").stream().allMatch(e -> e.index() == 0));
    }

    @Test
    @DisplayName("Empty and null content do not open or emit a text block")
    void emptyAndNullContentAreIgnored() {
        StreamingState state = new StreamingState();

        List<SseEvent> first = parse(state.processChunk(
                "{\"choices\":[{\"delta\":{\"role\":\"assistant\",\"content\":\"\"}}]}"));
        assertEquals(List.of("message_start", "ping"), names(first));

        assertEquals("", state.processChunk("{\"choices\":[{\"delta\":{\"content\":null}}]}"));

        List<SseEvent> afterText = parse(state.processChunk(textChunk("hi")));
        assertEquals(List.of("content_block_start", "content_block_delta"), names(afterText));
        assertEquals(0, single(afterText, "content_block_start").index());
        assertEquals("hi", textDeltas(afterText, 0));
    }

    @Test
    @DisplayName("Only the first choice of a chunk is translated")
    void onlyFirstChoiceIsTranslated() {
        StreamingState state = new StreamingState();

        List<SseEvent> events = parse(state.processChunk("{\"choices\":["
                + "{\"index\":0,\"delta\":{\"content\":\"first\"}},"
                + "{\"index\":1,\"delta\":{\"content\":\"second\"}}]}"));

        assertEquals("first", textDeltas(events, 0));
        assertFalse(textDeltas(events, 0).contains("second"));
    }

    @Test
    @DisplayName("Text content is forwarded verbatim, including JSON-special characters")
    void textContentIsForwardedVerbatim() {
        StreamingState state = new StreamingState();
        String payload = "a \"quoted\" \\ back\\slash\nnew line \u00e9\u00e8 \ud83d\ude00";

        List<SseEvent> events = parse(state.processChunk(textChunk("a \\\"quoted\\\" \\\\ back\\\\slash\\nnew line \u00e9\u00e8 \ud83d\ude00")));

        assertEquals(payload, textDeltas(events, 0));
    }

    // =====================================================================
    // Usage accounting
    // =====================================================================

    @Test
    @DisplayName("A usage-only chunk (empty choices) updates every token counter and emits nothing")
    void usageOnlyChunkUpdatesTokens() {
        StreamingState state = new StreamingState();
        state.processChunk(textChunk("hi"));

        String out = state.processChunk("{\"choices\":[],\"usage\":{"
                + "\"prompt_tokens\":11,\"completion_tokens\":7,"
                + "\"prompt_tokens_details\":{\"cached_tokens\":5,\"cache_write_tokens\":3}}}");

        assertEquals("", out);
        assertEquals(7, state.getOutputTokens());
        assertEquals(11, state.getInputTokens());
        assertEquals(5, state.getCachedTokens());
        assertEquals(3, state.getCacheWriteTokens());
    }

    @Test
    @DisplayName("A usage-only first chunk still emits message_start and ping")
    void usageOnlyFirstChunkEmitsMessageStart() {
        StreamingState state = new StreamingState();

        List<SseEvent> events = parse(state.processChunk(
                "{\"choices\":[],\"usage\":{\"prompt_tokens\":4,\"completion_tokens\":9}}"));

        assertEquals(List.of("message_start", "ping"), names(events));
        assertEquals(4, state.getInputTokens());
        assertEquals(9, state.getOutputTokens());
    }

    @Test
    @DisplayName("A chunk without choices and without usage emits nothing after the first chunk")
    void chunkWithoutChoicesOrUsageEmitsNothing() {
        StreamingState state = new StreamingState();
        state.processChunk(textChunk("hi"));

        assertEquals("", state.processChunk("{\"id\":\"late\"}"));
        assertEquals("", state.processChunk("{\"choices\":[]}"));
        assertEquals(0, state.getInputTokens());
        assertEquals(0, state.getOutputTokens());
    }

    @Test
    @DisplayName("A non-array choices value is handled like a usage-only chunk")
    void objectChoicesTreatedAsUsageOnly() {
        StreamingState state = new StreamingState();
        state.processChunk(textChunk("hi"));

        String out = state.processChunk(
                "{\"choices\":{},\"usage\":{\"prompt_tokens\":6,\"completion_tokens\":2}}");

        assertEquals("", out);
        assertEquals(6, state.getInputTokens());
        assertEquals(2, state.getOutputTokens());
    }

    @Test
    @DisplayName("Usage inside a chunk that does carry a choice is applied and reported in message_delta")
    void usageWithChoiceIsAppliedAndReportedInMessageDelta() {
        StreamingState state = new StreamingState();

        state.processChunk("{\"id\":\"c1\",\"model\":\"m\",\"choices\":[{\"delta\":{\"content\":\"ok\"},"
                + "\"finish_reason\":\"stop\"}],"
                + "\"usage\":{\"prompt_tokens\":30,\"completion_tokens\":42,"
                + "\"prompt_tokens_details\":{\"cached_tokens\":20}}}");

        assertEquals(30, state.getInputTokens());
        assertEquals(42, state.getOutputTokens());
        assertEquals(20, state.getCachedTokens());

        SseEvent messageDelta = single(parse(state.processChunk("[DONE]")), "message_delta");
        assertEquals(42, messageDelta.data().path("usage").path("output_tokens").asInt());
        assertEquals("end_turn", messageDelta.data().path("delta").path("stop_reason").asText());
    }

    @Test
    @DisplayName("Absent usage fields keep their previously accumulated values")
    void absentUsageFieldsRetainPreviousValues() {
        StreamingState state = new StreamingState();
        state.processChunk(textChunk("hi"));
        state.processChunk("{\"choices\":[],\"usage\":{\"prompt_tokens\":12,\"completion_tokens\":8,"
                + "\"prompt_tokens_details\":{\"cached_tokens\":4,\"cache_write_tokens\":2}}}");

        state.processChunk("{\"choices\":[],\"usage\":{\"completion_tokens\":9}}");

        assertEquals(9, state.getOutputTokens());
        assertEquals(12, state.getInputTokens());
        assertEquals(4, state.getCachedTokens());
        assertEquals(2, state.getCacheWriteTokens());
    }

    @Test
    @DisplayName("cache_write_tokens prefers input_tokens_details, then prompt_tokens_details, then the top level field")
    void cacheWriteTokensPrecedence() {
        StreamingState state = new StreamingState();
        state.processChunk(textChunk("hi"));

        state.processChunk("{\"choices\":[],\"usage\":{"
                + "\"input_tokens_details\":{\"cache_write_tokens\":99},"
                + "\"prompt_tokens_details\":{\"cache_write_tokens\":30},"
                + "\"cache_write_tokens\":1}}");
        assertEquals(99, state.getCacheWriteTokens());

        state.processChunk("{\"choices\":[],\"usage\":{"
                + "\"prompt_tokens_details\":{\"cache_write_tokens\":30},"
                + "\"cache_write_tokens\":1}}");
        assertEquals(30, state.getCacheWriteTokens());

        state.processChunk("{\"choices\":[],\"usage\":{\"cache_write_tokens\":1}}");
        assertEquals(1, state.getCacheWriteTokens());

        state.processChunk("{\"choices\":[],\"usage\":{\"completion_tokens\":1}}");
        assertEquals(1, state.getCacheWriteTokens(), "no cache-write information must keep the old value");
    }

    // =====================================================================
    // finish_reason mapping
    // =====================================================================

    @ParameterizedTest(name = "finish_reason {0} -> stop_reason {1}")
    @CsvSource({
            "length, max_tokens",
            "tool_calls, tool_use",
            "function_call, tool_use",
            "stop, end_turn",
            "content_filter, end_turn"
    })
    @DisplayName("OpenAI finish_reason values are mapped into the Anthropic stop_reason")
    void finishReasonIsMapped(String openAiReason, String expectedStopReason) {
        StreamingState state = new StreamingState();
        state.processChunk(textChunkWithFinish("text", openAiReason));

        SseEvent messageDelta = single(parse(state.processChunk("[DONE]")), "message_delta");

        assertEquals("message_delta", messageDelta.type());
        assertEquals(expectedStopReason, messageDelta.data().path("delta").path("stop_reason").asText());
        assertTrue(messageDelta.data().path("delta").path("stop_sequence").isNull());
    }

    @Test
    @DisplayName("Null and literal \"null\" finish_reason values leave the default stop_reason")
    void nullFinishReasonKeepsDefault() {
        StreamingState state = new StreamingState();
        state.processChunk("{\"choices\":[{\"index\":0,\"delta\":{\"content\":\"x\"},\"finish_reason\":null}]}");
        state.processChunk("{\"choices\":[{\"index\":0,\"delta\":{},\"finish_reason\":\"null\"}]}");

        SseEvent messageDelta = single(parse(state.processChunk("[DONE]")), "message_delta");
        assertEquals("end_turn", messageDelta.data().path("delta").path("stop_reason").asText());
    }

    // =====================================================================
    // [DONE] handling
    // =====================================================================

    @Test
    @DisplayName("[DONE] without any prior chunk only closes the message")
    void doneWithoutPriorChunk() {
        StreamingState state = new StreamingState();

        List<SseEvent> events = parse(state.processChunk("[DONE]"));

        assertTrue(state.isDoneReceived());
        assertFalse(state.isMessageStarted());
        assertEquals(List.of("message_delta", "message_stop"), names(events));

        SseEvent messageDelta = events.get(0);
        assertEquals("end_turn", messageDelta.data().path("delta").path("stop_reason").asText());
        assertEquals(0, messageDelta.data().path("usage").path("output_tokens").asInt());

        SseEvent messageStop = events.get(1);
        assertEquals("message_stop", messageStop.type());
    }

    @Test
    @DisplayName("[DONE] after text content closes the open text block and stops the message")
    void doneAfterContentClosesTextBlock() {
        StreamingState state = new StreamingState();
        state.processChunk(textChunkWithFinish("Hello", "stop"));

        List<SseEvent> events = parse(state.processChunk("[DONE]"));

        assertEquals(List.of("content_block_stop", "message_delta", "message_stop"), names(events));
        assertEquals(List.of(0), stopIndexes(events));
        assertTrue(textDeltas(events, 0).isEmpty(), "no synthetic notice may be injected when text was produced");
        assertEquals("end_turn", single(events, "message_delta").data().path("delta").path("stop_reason").asText());
        assertEquals("message_stop", single(events, "message_stop").type());
        assertTrue(state.isDoneReceived());
    }

    @Test
    @DisplayName("[DONE] with no content injects an empty-response notice text block with default context")
    void doneWithoutContentInjectsEmptyResponseNotice() {
        StreamingState state = new StreamingState();
        state.processChunk("{\"id\":\"c1\",\"model\":\"m\","
                + "\"choices\":[{\"index\":0,\"delta\":{\"role\":\"assistant\"},\"finish_reason\":\"stop\"}]}");

        List<SseEvent> events = parse(state.processChunk("[DONE]"));

        assertEquals(List.of("content_block_start", "content_block_delta", "content_block_stop",
                "message_delta", "message_stop"), names(events));

        SseEvent blockStart = events.get(0);
        assertEquals(0, blockStart.index());
        assertEquals("text", blockStart.data().path("content_block").path("type").asText());

        String notice = textDeltas(events, 0);
        assertTrue(notice.startsWith("[Proxy] The provider returned an empty response (no text, no tool calls)"),
                "unexpected notice: " + notice);
        assertTrue(notice.contains("finish_reason=end_turn"), "unexpected notice: " + notice);
        assertTrue(notice.contains("Try /compact, or start a new session."), "unexpected notice: " + notice);
        assertFalse(notice.contains("Last request:"), "no request context is known for the default constructor");

        assertEquals(List.of(0), stopIndexes(events));
        assertTrue(state.isDoneReceived());
    }

    @Test
    @DisplayName("[DONE] notice reports the request message count and human readable request size")
    void doneNoticeIncludesRequestContext() {
        StreamingState kilobytes = new StreamingState(5, 2048);
        kilobytes.processChunk("{\"choices\":[{\"delta\":{}}]}");
        String kbNotice = textDeltas(parse(kilobytes.processChunk("[DONE]")), 0);
        assertTrue(kbNotice.contains("Last request: 5 messages, 2.0 KB"), "unexpected notice: " + kbNotice);

        StreamingState bytes = new StreamingState(0, 512);
        bytes.processChunk("{\"choices\":[{\"delta\":{}}]}");
        String byteNotice = textDeltas(parse(bytes.processChunk("[DONE]")), 0);
        assertTrue(byteNotice.contains("Last request: 0 messages, 512 bytes"), "unexpected notice: " + byteNotice);

        StreamingState megabytes = new StreamingState(12, 3L * 1024 * 1024);
        megabytes.processChunk("{\"choices\":[{\"delta\":{}}]}");
        String mbNotice = textDeltas(parse(megabytes.processChunk("[DONE]")), 0);
        assertTrue(mbNotice.contains("Last request: 12 messages, 3.0 MB"), "unexpected notice: " + mbNotice);
    }

    @Test
