    // =====================================================================
    // Reasoning / thinking blocks
    // =====================================================================

    @Test
    @DisplayName("Reasoning deltas open a thinking block, accumulate, then get closed by text")
    void reasoningOpensThinkingBlockClosedByText() {
        StreamingState state = new StreamingState();

        List<SseEvent> first = parse(state.processChunk(reasoningChunk("Let me think")));
        assertEquals(List.of("message_start", "ping", "content_block_start", "content_block_delta"), names(first));
        SseEvent start = first.get(2);
        assertEquals(0, start.index());
        assertEquals("thinking", start.data().path("content_block").path("type").asText());
        assertEquals("", start.data().path("content_block").path("thinking").asText());
        SseEvent delta = first.get(3);
        assertEquals(0, delta.index());
        assertEquals("thinking_delta", delta.data().path("delta").path("type").asText());
        assertEquals("Let me think", delta.data().path("delta").path("thinking").asText());

        List<SseEvent> second = parse(state.processChunk(reasoningChunk(" harder")));
        assertEquals(List.of("content_block_delta"), names(second), "the thinking block must not be reopened");
        assertEquals("harder", second.get(0).data().path("delta").path("thinking").asText());

        List<SseEvent> third = parse(state.processChunk(textChunk("Answer")));
        assertEquals(List.of("content_block_delta", "content_block_stop", "content_block_start",
                "content_block_delta"), names(third));

        SseEvent signature = third.get(0);
        assertEquals(0, signature.index());
        assertEquals("signature_delta", signature.data().path("delta").path("type").asText());

        assertEquals(0, third.get(1).index(), "the thinking block must be stopped before text starts");
