        List<SseEvent> events = parse(state.processChunk("[DONE]"));

        assertTrue(named(events, "content_block_start").stream()
                        .anyMatch(e -> "text".equals(e.data().path("content_block").path("type").asText())),
                "a notice text block must be started: " + names(events));
        assertTrue(named(events, "content_block_delta").stream()
                        .anyMatch(e -> "signature_delta".equals(e.data().path("delta").path("type").asText())),
                "the thinking block must receive a signature before it closes");
        assertTrue(named(events, "content_block_delta").stream()
                        .anyMatch(e -> "text_delta".equals(e.data().path("delta").path("type").asText())
                                && e.data().path("delta").path("text").asText().contains("[Proxy] The provider returned an empty response")),
                "the notice text must be emitted: " + names(events));

        assertEquals(List.of(0, 1), stopIndexes(events).stream().sorted().collect(Collectors.toList()),
                "both the thinking block and the notice text block must be stopped");

        List<String> eventNames = names(events);
        int lastStop = eventNames.lastIndexOf("content_block_stop");
        assertTrue(lastStop < eventNames.indexOf("message_delta"),
                "all blocks must be stopped before message_delta: " + eventNames);
        assertEquals("message_stop", eventNames.get(eventNames.size() - 1));
    }

