    @Test
    @DisplayName("message_start and ping are emitted only for the first chunk")
    void messageStartEmittedOnlyOnce() {
        StreamingState state = new StreamingState();

        List<SseEvent> first = parse(state.processChunk(
                "{\"id\":\"first-id\",\"model\":\"first-model\",\"choices\":[{\"delta\":{\"content\":\"a\"}}]}"));
        List<SseEvent> second = parse(state.processChunk(
                "{\"id\":\"second-id\",\"model\":\"second-model\",\"choices\":[{\"delta\":{\"content\":\"b\"}}]}"));

        assertEquals(List.of("message_start", "ping", "content_block_start", "content_block_delta"),
                names(first));
        assertEquals(List.of("content_block_delta"), names(second));
        assertEquals("first-id",
                single(first, "message_start").data().path("message").path("id").asText());
        assertTrue(textDeltas(first, 0).equals("a") && textDeltas(second, 0).equals("b"),
                "each chunk's text must be forwarded to the same block");
    }

    // =====================================================================
    // Text streaming
    // =====================================================================

    @Test
    @DisplayName("Successive text fragments share one text block and one index")
    void textFragmentsShareOneTextBlock() {
        StreamingState state = new StreamingState();

        List<SseEvent> first = parse(state.processChunk(textChunk("Hel")));
        List<SseEvent> second = parse(state.processChunk(textChunk("lo ")));
        List<SseEvent> third = parse(state.processChunk(textChunk("world")));

        assertEquals(1, named(first, "content_block_start").size(), "text block must open exactly once");
        assertTrue(named(second, "content_block_start").isEmpty());
        assertTrue(named(third, "content_block_start").isEmpty());

        List<SseEvent> all = new ArrayList<>();
        all.addAll(first);
        all.addAll(second);
        all.addAll(third);
        assertEquals("Hello world", textDeltas(all, 0));
        assertEquals(3, named(all, "content_block_delta").size());
        assertTrue(named(all, "content_block_delta").stream().allMatch(e -> e.index() == 0));
    }

    @Test
    @DisplayName("Empty and null content do not open or emit a text block")
    void emptyAndNullContentAreIgnored() {
        StreamingState state = new StreamingState();

        List<SseEvent> first = parse(state.processChunk(
                "{\"choices\":[{\"delta\":{\"role\":\"assistant\",\"content\":\"\"}}]}"));
        assertEquals(List.of("message_start", "ping"), names(first));

        assertEquals("", state.processChunk("{\"choices\":[{\"delta\":{\"content\":null}}]}"));

        List<SseEvent> afterText = parse(state.processChunk(textChunk("hi")));
        assertEquals(List.of("content_block_start", "content_block_delta"), names(afterText));
        assertEquals(0, single(afterText, "content_block_start").index());
        assertEquals("hi", textDeltas(afterText, 0));
    }

