class AnthropicToOpenAITranslatorProcessChunkTests {

    private static final ObjectMapper JSON = new ObjectMapper();

    // ---------------------------------------------------------------------
    // SSE parsing helpers
    // ---------------------------------------------------------------------

    /** One parsed SSE frame: the {@code event:} name and the parsed {@code data:} JSON. */
    private record SseEvent(String name, JsonNode data) {

        String type() {
            return data.path("type").asText();
        }

        int index() {
            return data.path("index").asInt(-999);
        }
    }

    private static List<SseEvent> parse(String sse) {
        List<SseEvent> events = new ArrayList<>();
        if (sse == null || sse.isEmpty()) {
            return events;
        }
        for (String block : sse.split("\n\n")) {
            if (block.isBlank()) {
                continue;
            }
            String name = null;
            String data = null;
            for (String line : block.split("\n", -1)) {
                if (line.startsWith("event: ")) {
                    name = line.substring("event: ".length());
                } else if (line.startsWith("data: ")) {
                    data = line.substring("data: ".length());
                }
            }
            assertNotNull(name, "SSE frame without an event name: " + block);
            assertNotNull(data, "SSE frame without a data line: " + block);
            try {
                events.add(new SseEvent(name, JSON.readTree(data)));
            } catch (Exception e) {
                throw new AssertionError("SSE data line is not valid JSON: " + data, e);
            }
        }
        return events;
    }

    private static List<SseEvent> process(StreamingState state, String... dataLines) {
        List<SseEvent> events = new ArrayList<>();
        for (String line : dataLines) {
            events.addAll(parse(state.processChunk(line)));
        }
        return events;
    }

    private static List<String> names(List<SseEvent> events) {
        return events.stream().map(SseEvent::name).collect(Collectors.toList());
    }

    private static List<Integer> stopIndexes(List<SseEvent> events) {
        return events.stream()
                .filter(e -> "content_block_stop".equals(e.name()))
                .map(SseEvent::index)
                .collect(Collectors.toList());
    }

    private static List<SseEvent> named(List<SseEvent> events, String eventName) {
        return events.stream().filter(e -> eventName.equals(e.name())).collect(Collectors.toList());
    }

    private static SseEvent single(List<SseEvent> events, String eventName) {
        List<SseEvent> matching = named(events, eventName);
        assertEquals(1, matching.size(), "expected exactly one '" + eventName + "' event in " + names(events));
        return matching.get(0);
    }

    /** Delta-text fragments carried by {@code content_block_delta} frames of type {@code text_delta}. */
    private static String textDeltas(List<SseEvent> events, int blockIndex) {
        StringBuilder sb = new StringBuilder();
        for (SseEvent e : events) {
            if ("content_block_delta".equals(e.name())
                    && "text_delta".equals(e.data().path("delta").path("type").asText())
                    && e.index() == blockIndex) {
                sb.append(e.data().path("delta").path("text").asText());
            }
        }
        return sb.toString();
    }

    // ---------------------------------------------------------------------
    // Chunk builders (only the fields the target reads)
    // ---------------------------------------------------------------------

    private static String textChunk(String text) {
        return "{\"choices\":[{\"index\":0,\"delta\":{\"content\":\"" + text + "\"}}]}";
    }

    private static String textChunkWithFinish(String text, String finishReason) {
        return "{\"choices\":[{\"index\":0,\"delta\":{\"content\":\"" + text + "\"},"
                + "\"finish_reason\":\"" + finishReason + "\"}]}";
    }

    private static String reasoningChunk(String reasoning) {
        return "{\"choices\":[{\"index\":0,\"delta\":{\"reasoning_content\":\"" + reasoning + "\"}}]}";
    }

    private static String toolStartChunk(int index, String id, String name) {
        return "{\"choices\":[{\"index\":0,\"delta\":{\"tool_calls\":[{\"index\":" + index
                + ",\"id\":\"" + id + "\",\"type\":\"function\",\"function\":{\"name\":\"" + name
                + "\",\"arguments\":\"\"}}]}}]}";
    }

    private static String toolArgsChunk(int index, String argumentsJson) {
        return "{\"choices\":[{\"index\":0,\"delta\":{\"tool_calls\":[{\"index\":" + index
                + ",\"function\":{\"arguments\":" + JSON_STRING(argumentsJson) + "}}]}}]}";
    }

    private static String JSON_STRING(String raw) {
        try {
            return JSON.writeValueAsString(raw);
        } catch (Exception e) {
            throw new IllegalStateException(e);
        }
