        assertEquals("", state.processChunk("{broken"));
        // "[DONE] " is not exactly "[DONE]", so it is treated as (invalid) JSON.
        assertEquals("", state.processChunk("[DONE] "));

        assertFalse(state.isMessageStarted(), "invalid JSON must not start a message");
        assertFalse(state.isDoneReceived(), "invalid JSON must not mark the stream as done");
        assertEquals(0, state.getInputTokens());
        assertEquals(0, state.getOutputTokens());
