        } catch (IOException e) { /* ignore */ }
    }

    String dir = workingDir;
    workingDir = null;
    if (dir != null) {
        try {
            cleanupSettingsLocalJson(dir);
        } catch (IOException e) {
            LOG.warning("Could not clean up .claude/settings.local.json: " + e.getMessage());
        }
    }
}

