import io.github.nbplugins.claudecodegui.settings.ClaudeProfile;
import io.github.nbplugins.claudecodegui.settings.ProxyConfiguration;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.NullSource;
import org.junit.jupiter.params.provider.ValueSource;
import org.netbeans.junit.MockServices;
import org.openbeans.claude.netbeans.ClaudeCodeStatusService;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Behavioural tests for {@link ClaudeProcess#start(String, ClaudeProfile, String, SessionMode, String)}.
 *
 * <p>The tests use a temporary shell script as the Claude executable.  The script records its
 * working directory, argv and environment, then sleeps so that the returned PTY can be stopped
 * deterministically.  Lookup is provided by a mutable test service and preferences use NB JUnit's
 * in-memory PreferencesFactory.</p>
 */
public class ClaudeProcessStartTests {

    static {
        // Must be set before java.util.prefs.Preferences is first initialised.
        System.setProperty("java.util.prefs.PreferencesFactory",
                "org.netbeans.junit.internal.MemoryPreferencesFactory");
    }

    private static final ObjectMapper MAPPER = new ObjectMapper();

    @TempDir
    Path tempDir;

    private Path workingDir;
    private Path secondWorkingDir;
    private Path captureFile;
    private Path profilesDir;
    private Path executable;
    private final List<ClaudeProcess> startedProcesses = new CopyOnWriteArrayList<>();

    @BeforeEach
    void setUp() throws IOException {
        workingDir = Files.createDirectories(tempDir.resolve("work"));
        secondWorkingDir = Files.createDirectories(tempDir.resolve("work-2"));
        captureFile = tempDir.resolve("process-capture.txt");
        profilesDir = Files.createDirectories(tempDir.resolve("profiles"));
        executable = createRecordingExecutable(captureFile);

        FakeStatusService.reset();
        MockServices.setServices(FakeStatusService.class);

        ClaudeCodePreferences.setClaudeExecutablePath(executable.toString());
        ClaudeCodePreferences.setProfilesDir(profilesDir);
        ClaudeCodePreferences.setMcpEnabled(true);
    }

    @AfterEach
    void tearDown() {
        for (ClaudeProcess process : startedProcesses) {
            try {
                process.stop();
            } catch (RuntimeException ignored) {
                // Keep all launched processes from leaking even if a test assertion already failed.
            }
        }
        startedProcesses.clear();
        FakeStatusService.reset();
        ClaudeCodePreferences.setMcpEnabled(true);
    }

    @ParameterizedTest
    @NullSource
    @ValueSource(strings = {"", "   ", "\t\n"})
    void rejectsNullAndBlankWorkingDirectories(String invalidWorkingDir) {
        ClaudeProcess process = new ClaudeProcess();

        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> process.start(invalidWorkingDir, null, "", SessionMode.NEW, null));

        assertEquals("workingDir must not be blank", ex.getMessage());
        assertFalse(Files.exists(captureFile), "no child process should be launched");
    }

    @Test
    void launchesConfiguredExecutableWithExtraArgsInWorkingDirectory() throws Exception {
        ClaudeProcess process = newProcess();

        PtyProcess pty = process.start(workingDir.toString(), null,
                "--verbose --dangerously-skip-permissions", SessionMode.NEW, "ignored-session-id");

        assertNotNull(pty);
        assertTrue(process.getLastCommand().startsWith(executable.toString()));
        CapturedProcess captured = awaitCapture(captureFile);
        assertEquals("--verbose", captured.args().get(0));
        assertEquals("--dangerously-skip-permissions", captured.args().get(1));
        assertEquals(2, captured.args().size(), "NEW mode alone must not append session flags");
        assertEquals(workingDir.toAbsolutePath().toString(), captured.pwd());
        assertEquals("xterm-256color", captured.env().get("TERM"));
        assertFalse(Files.exists(workingDir.resolve(".claude/settings.local.json")),
                "without a running MCP service, start() must not write settings.local.json");
    }

    @Test
    void appliesProfileExtraEnvironmentVariables() throws Exception {
        ClaudeProfile profile = ClaudeProfile.createNamed("EnvProfile");
        profile.setStorageDir(tempDir.resolve("env-profile-config").toString());
        profile.setExtraEnvVars(List.<String[]>of(
                new String[]{"CLAUDE_PROCESS_TEST_MARKER", "marker-value"}));
        ClaudeProcess process = newProcess();

        process.start(workingDir.toString(), profile, "", SessionMode.NEW, null);

        CapturedProcess captured = awaitCapture(captureFile);
        assertEquals("marker-value", captured.env().get("CLAUDE_PROCESS_TEST_MARKER"));
        assertEquals(profile.getStorageDir(), captured.env().get("CLAUDE_CONFIG_DIR"));
    }

    @Test
    void resumeSpecificAppendsResumeFlagAndSessionId() throws Exception {
        ClaudeProcess process = newProcess();

        process.start(workingDir.toString(), null, "", SessionMode.RESUME_SPECIFIC, "session-123");

        CapturedProcess captured = awaitCapture(captureFile);
        assertEquals(List.of("--resume", "session-123"), captured.args());
    }

    @Test
    void resumeSpecificWithBlankSessionIdDoesNotAppendResumeFlag() throws Exception {
        ClaudeProcess process = newProcess();

        process.start(workingDir.toString(), null, "", SessionMode.RESUME_SPECIFIC, "   ");

        CapturedProcess captured = awaitCapture(captureFile);
        assertTrue(captured.args().isEmpty(), "blank resume id should start a fresh session");
    }

    @Test
    void continueLastDoesNotAppendFlagWhenNoSessionExists() throws Exception {
        ClaudeProfile profile = continuousProfile();
        ClaudeProcess process = newProcess();

        process.start(workingDir.toString(), profile, "", SessionMode.CONTINUE_LAST, null);

        CapturedProcess captured = awaitCapture(captureFile);
        assertFalse(captured.args().contains("--continue"));
    }

    @Test
    void continueLastAppendsFlagWhenSessionJsonlExists() throws Exception {
        ClaudeProfile profile = continuousProfile();
        Path sessionDir = Path.of(profile.getStorageDir())
                .resolve("projects").resolve(ClaudeSessionStore.computeHash(workingDir));
        Files.createDirectories(sessionDir);
        Files.writeString(sessionDir.resolve("existing-session.jsonl"), "{}\n", StandardCharsets.UTF_8);
        ClaudeProcess process = newProcess();

        process.start(workingDir.toString(), profile, "", SessionMode.CONTINUE_LAST, null);

        CapturedProcess captured = awaitCapture(captureFile);
        assertEquals(List.of("--continue"), captured.args());
    }

    @Test
    void runningMcpWritesConfigAndSettingsAndStopRemovesThem() throws Exception {
        FakeStatusService.running.set(true);
        FakeStatusService.port.set(45678);
        ClaudeProcess process = newProcess();

        process.start(workingDir.toString(), null, "", SessionMode.NEW, null);

        CapturedProcess captured = awaitCapture(captureFile);
        int configFlag = captured.args().indexOf("--mcp-config");
        assertTrue(configFlag >= 0, "running MCP server should add --mcp-config");
        assertEquals(2, captured.args().size());
        Path mcpConfigFile = Path.of(captured.args().get(configFlag + 1));
        assertTrue(Files.exists(mcpConfigFile));
        JsonNode mcpConfig = MAPPER.readTree(Files.readString(mcpConfigFile));
        assertEquals("sse", mcpConfig.path("mcpServers").path("netbeans").path("type").asText());
        assertEquals("http://127.0.0.1:45678/sse",
                mcpConfig.path("mcpServers").path("netbeans").path("url").asText());

        Path settingsFile = workingDir.resolve(".claude/settings.local.json");
        assertTrue(Files.exists(settingsFile));
        JsonNode settings = MAPPER.readTree(Files.readString(settingsFile));
        assertEquals("http://127.0.0.1:45678/hook",
                settings.path("hooks").path("PreToolUse").get(0).path("hooks").get(0).path("url").asText());
        assertEquals("http://127.0.0.1:45678/stop",
                settings.path("hooks").path("Stop").get(0).path("hooks").get(0).path("url").asText());
        assertEquals("http://127.0.0.1:45678/permission-request",
                settings.path("hooks").path("PermissionRequest").get(0).path("hooks").get(0).path("url").asText());
        List<String> allowed = new ArrayList<>();
        settings.path("permissions").path("allow").forEach(node -> allowed.add(node.asText()));
        assertTrue(allowed.contains("mcp__netbeans__show_markdown"));
        assertTrue(allowed.contains("mcp__netbeans__show_markdown_file"));

        process.stop();
        assertFalse(Files.exists(mcpConfigFile), "stop() should delete the temporary MCP config");
        assertFalse(Files.exists(settingsFile), "stop() should delete a plugin-only settings file");
    }

    @Test
    void disablingMcpSkipsConfigArgButStillMergesSettingsWhenServerRuns() throws Exception {
        FakeStatusService.running.set(true);
        FakeStatusService.port.set(46001);
        ClaudeCodePreferences.setMcpEnabled(false);
        ClaudeProcess process = newProcess();

        process.start(workingDir.toString(), null, "", SessionMode.NEW, null);

