    private CapturedProcess awaitCapture(Path capturePath) throws Exception {
        long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
        while (!Files.exists(capturePath) && System.nanoTime() < deadline) {
            Thread.sleep(20);
        }
        assertTrue(Files.exists(capturePath), "child process did not write its capture file");
        String text = Files.readString(capturePath, StandardCharsets.UTF_8);
        String[] lines = text.split("\\R", -1);
        String pwd = null;
        List<String> args = new ArrayList<>();
        Map<String, String> env = new LinkedHashMap<>();
        int section = 0;
        for (String line : lines) {
            if (line.equals("__ARGV__")) {
                section = 1;
                continue;
            }
            if (line.equals("__ENV__")) {
                section = 2;
                continue;
            }
            if (section == 0 && line.startsWith("PWD=")) {
                pwd = line.substring("PWD=".length());
            } else if (section == 1 && line.startsWith("ARG=")) {
                args.add(line.substring("ARG=".length()));
            } else if (section == 2) {
                int equals = line.indexOf('=');
                if (equals > 0) {
                    env.put(line.substring(0, equals), line.substring(equals + 1));
                }
            }
        }
        return new CapturedProcess(pwd, List.copyOf(args), Map.copyOf(env));
    }

