package io.github.nbplugins.claudecodegui.process;

import io.github.nbplugins.claudecodegui.model.ChoiceMenuModel;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Behavioural tests for
 * {@link ScreenContentDetector#detectUnnumberedChoiceMenu(List)}.
 *
 * <p>The detector reads an already-rendered terminal screen (a list of rows) and
 * reconstructs an unnumbered picker: entries are usually two rows (label + a
 * metadata/description row that carries the {@code ·} separator), the selected
 * entry is prefixed with a cursor glyph, and the footer carries navigation hints.
 */
class ScreenContentDetectorDetectUnnumberedChoiceMenuTests {

    private static final String CURSOR = "\u276F";          // ❯
    private static final String CURSOR_TRIANGLE = "\u25B6"; // ▶
    private static final String DOT = "\u00B7";             // ·
    private static final String SEPARATOR = "\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500";
    private static final String BOX_TOP = "\u256D" + SEPARATOR + "\u256E"; // ╭…╮
    private static final String BOX_BOTTOM = "\u2570" + SEPARATOR + "\u256F";
    private static final String BOX_SIDE = "\u2502";        // │
    private static final String SEARCH_GLYPH = "\u2315";    // ⌕
    private static final String FOOTER = "\u2191\u2193 to navigate " + DOT + " Esc to cancel";

    private static ScreenContentDetector detector() {
        return new ScreenContentDetector();
    }

    private static List<String> screen(String... lines) {
        return new ArrayList<>(Arrays.asList(lines));
    }

    private static ChoiceMenuModel detect(List<String> lines) {
        Optional<ChoiceMenuModel> result = detector().detectUnnumberedChoiceMenu(lines);
        assertTrue(result.isPresent(), "expected an unnumbered choice menu to be detected");
        return result.orElseThrow();
    }

    private static void assertOption(ChoiceMenuModel.Option option,
                                     String display, String response, String description) {
        assertNotNull(option);
        assertEquals(display, option.display());
        assertEquals(response, option.response());
        assertEquals(description, option.description());
        assertFalse(option.checked());
        assertFalse(option.hasCheckbox());
        assertFalse(option.hasTextInput());
    }

    // ---------------------------------------------------------------------
    // Invalid / empty input
    // ---------------------------------------------------------------------

    @Test
    @DisplayName("null screen yields no menu")
    void nullScreenYieldsNoMenu() {
        assertEquals(Optional.empty(), detector().detectUnnumberedChoiceMenu(null));
    }

    @Test
    @DisplayName("empty screen yields no menu")
    void emptyScreenYieldsNoMenu() {
        assertEquals(Optional.empty(), detector().detectUnnumberedChoiceMenu(screen()));
    }

