    static final class FakeDiff extends Diff {
        final FakeDiffView view = new FakeDiffView();
        final List<Request> requests = new ArrayList<>();
        IOException failure;
        boolean returnNull;

        static final class Request {
            final String oldName;
            final String oldTitle;
            final String oldContent;
            final String newName;
            final String newTitle;
            final String newContent;
            final String mimeType;

            Request(String oldName, String oldTitle, String oldContent,
                    String newName, String newTitle, String newContent, String mimeType) {
                this.oldName = oldName;
                this.oldTitle = oldTitle;
                this.oldContent = oldContent;
                this.newName = newName;
                this.newTitle = newTitle;
                this.newContent = newContent;
                this.mimeType = mimeType;
            }
        }

        @Override
        public Component createDiff(String name1, String title1, Reader reader1,
                                    String name2, String title2, Reader reader2,
                                    String mimeType) {
            throw new AssertionError("open() must use the StreamSource overload");
        }

        @Override
        public DiffView createDiff(StreamSource oldSource, StreamSource newSource) throws IOException {
            try {
                requests.add(new Request(
                        oldSource.getName(), oldSource.getTitle(), readFully(oldSource.createReader()),
                        newSource.getName(), newSource.getTitle(), readFully(newSource.createReader()),
                        oldSource.getMIMEType()));
            } catch (IOException ex) {
                throw ex;
            }
            if (failure != null) {
                throw failure;
            }
            return returnNull ? null : view;
        }
    }

    static String readFully(Reader reader) throws IOException {
        if (reader == null) {
            return null;
        }
        StringBuilder sb = new StringBuilder();
        char[] buffer = new char[512];
        int read;
        while ((read = reader.read(buffer)) >= 0) {
            sb.append(buffer, 0, read);
        }
        return sb.toString();
    }

