    // -------------------------------------------------------------------------
    // Helpers
    // -------------------------------------------------------------------------

    static final class Counters {
        final AtomicInteger accepts = new AtomicInteger();
        final AtomicInteger declines = new AtomicInteger();
        final AtomicInteger cancels = new AtomicInteger();
        final AtomicInteger closes = new AtomicInteger();
        final java.util.concurrent.atomic.AtomicReference<String> lastReason =
                new java.util.concurrent.atomic.AtomicReference<>();
        final Consumer<String> declineReason = reason -> {
            lastReason.set(reason);
            declines.incrementAndGet();
        };

        void close() {
            closes.incrementAndGet();
        }

        void cancel() {
            cancels.incrementAndGet();
        }
    }

    private Path writeFile(String name, String before, String after) throws IOException {
        Path file = tempDir.resolve(name);
        Files.writeString(file, after);
        return file;
    }

    private void openDiff(String filePath, String before, String after, String tabName,
                          String hookCwd, Counters counters) throws Exception {
        FileDiffOpener.open(filePath, before, after, tabName, hookCwd,
                counters::accept, counters.declineReason, counters::cancel, counters::close);
        flushEdt();
        flushEdt();
    }

    private static void flushEdt() throws Exception {
        if (java.awt.GraphicsEnvironment.isHeadless()) {
            // Cannot use invokeAndWait-safe Swing without a toolkit; still drain the queue.
            java.awt.EventQueue.invokeAndWait(() -> { });
            return;
        }
        SwingUtilities.invokeAndWait(() -> { });
    }

    private TopComponent singleOpenedWindow() {
        assertEquals(1, windowManager.registry.opened.size(),
                "exactly one diff window is expected to be open");
        return windowManager.registry.opened.iterator().next();
    }

    private FakeDiff.Request singleRequest() {
        assertEquals(1, diff.requests.size(), "exactly one diff must be requested");
        return diff.requests.get(0);
    }

    static <T> T single(Container root, Class<T> type) {
        List<T> found = findAll(root, type);
        assertEquals(1, found.size(), "expected exactly one " + type.getSimpleName() + " but found " + found);
        return found.get(0);
    }

    static <T> List<T> findAll(Container root, Class<T> type) {
        List<T> result = new ArrayList<>();
        collect(root, type, result);
        return result;
    }

    private static <T> void collect(Container root, Class<T> type, List<T> result) {
        for (Component child : root.getComponents()) {
            if (type.isInstance(child)) {
                result.add(type.cast(child));
            }
            if (child instanceof Container container) {
                collect(container, type, result);
            }
        }
    }

    static boolean containsComponent(Container root, Component component) {
        if (root == component) {
            return true;
        }
        for (Component child : root.getComponents()) {
            if (child == component) {
                return true;
            }
            if (child instanceof Container container && containsComponent(container, component)) {
                return true;
            }
        }
        return false;
    }

    static JLabel warningLabel(Container panel) {
        List<JLabel> labels = findAll(panel, JLabel.class);
        assertFalse(labels.isEmpty(), "the permission panel must expose a warning label");
        return labels.get(0);
    }

    static AbstractButton buttonEndingWith(Container root, String suffix) {
        for (AbstractButton button : findAll(root, AbstractButton.class)) {
            String text = button.getText();
            if (text != null && text.endsWith(suffix)) {
                return button;
            }
        }
        throw new AssertionError("no button ending with '" + suffix + "' in " + root);
    }

    static AbstractButton buttonContaining(Container root, String part) {
        for (AbstractButton button : findAll(root, AbstractButton.class)) {
            String text = button.getText();
            if (text != null && text.contains(part)) {
                return button;
            }
        }
        throw new AssertionError("no button containing '" + part + "' in " + root);
    }

    /** Runs a test body only when a display is available; otherwise JUnit reports it as aborted. */
    private static void withDisplay(ThrowingRunnable body) {
        org.junit.jupiter.api.Assumptions.assumeFalse(java.awt.GraphicsEnvironment.isHeadless(),
                "a display is required to build the Swing diff window");
        try {
            body.run();
        } catch (RuntimeException | Error ex) {
            throw ex;
        } catch (Exception ex) {
            throw new AssertionError(ex);
        }
    }

    interface ThrowingRunnable {
        void run() throws Exception;
    }

    // -------------------------------------------------------------------------
    // Display bootstrap
    // -------------------------------------------------------------------------

    /**
     * Makes sure AWT can talk to an X server. The variable is injected at the native level
     * (JNA) because AWT reads {@code DISPLAY} from the process environment, which cannot be
     * changed from pure Java. If no display can be arranged, the GUI tests are skipped.
     */
    static final class TestDisplay {
        interface LibC extends Library {
            int setenv(String name, String value, int overwrite);
        }

        private static Process ownedServer;

        static synchronized void ensure() {
            try {
                if (System.getenv("DISPLAY") != null) {
                    return;
                }
                String number = existingDisplayNumber();
                if (number == null) {
                    number = startXvfb();
                }
                if (number == null) {
                    return;
                }
                LibC libc = Native.load("c", LibC.class);
                if (libc.setenv("DISPLAY", ":" + number, 1) != 0) {
                    return;
                }
                System.setProperty("java.awt.headless", "false");
            } catch (Throwable ignored) {
                // Stay headless; GUI tests will be skipped by the assumption guard.
            }
        }

        private static String existingDisplayNumber() {
            File[] sockets = new File("/tmp/.X11-unix").listFiles((dir, name) -> name.matches("X\\d+"));
            if (sockets == null || sockets.length == 0) {
                return null;
            }
            List<File> sorted = new ArrayList<>(List.of(sockets));
            sorted.sort(Comparator.comparing(File::getName));
            for (File socket : sorted) {
                if ("X99".equals(socket.getName())) {
                    return "99";
                }
            }
            return sorted.get(0).getName().substring(1);
        }

        private static String startXvfb() throws Exception {
            File binary = new File("/usr/bin/Xvfb");
            if (!binary.canExecute()) {
                return null;
            }
            for (int number = 90; number < 100; number++) {
                File socket = new File("/tmp/.X11-unix/X" + number);
                if (socket.exists()) {
                    continue;
                }
                Process process = new ProcessBuilder(binary.getAbsolutePath(), ":" + number,
                        "-screen", "0", "1280x1024x24", "-nolisten", "tcp")
                        .redirectErrorStream(true)
                        .redirectOutput(ProcessBuilder.Redirect.DISCARD)
                        .start();
                for (int i = 0; i < 100; i++) {
                    if (socket.exists()) {
                        ownedServer = process;
                        Runtime.getRuntime().addShutdownHook(new Thread(process::destroy));
                        return String.valueOf(number);
                    }
                    if (!process.isAlive()) {
                        break;
                    }
                    Thread.sleep(50);
                }
                process.destroy();
            }
            return null;
        }
    }
