    // Session tab double
    // -------------------------------------------------------------------------

    /**
     * A real {@link ClaudeSessionTab} whose working directory, edit mode and embedded-diff
     * behaviour are controlled by the test.
     */
    static final class StubSessionTab extends ClaudeSessionTab {
        private final File workingDirectory;
        final List<EditMode> editModes = Collections.synchronizedList(new ArrayList<>());
        int requestActiveCalls;
        int hideEmbeddedCalls;
        int lastEmbedCalls;
        boolean embedResult;
        EmbeddedCall lastEmbed;

        static final class EmbeddedCall {
            final boolean outsideProject;
            final String outsideWarning;
            final JToolBar toolbar;
            final Component diffComponent;
            final FileDiffPermissionPanel permPanel;
            final Runnable onTabClose;

            EmbeddedCall(boolean outsideProject, String outsideWarning, JToolBar toolbar,
                         Component diffComponent, FileDiffPermissionPanel permPanel, Runnable onTabClose) {
                this.outsideProject = outsideProject;
                this.outsideWarning = outsideWarning;
                this.toolbar = toolbar;
                this.diffComponent = diffComponent;
                this.permPanel = permPanel;
                this.onTabClose = onTabClose;
            }
        }

        private StubSessionTab(File workingDirectory) {
            super(workingDirectory);
            this.workingDirectory = workingDirectory;
        }

        @Override
        public File getWorkingDirectory() {
            return workingDirectory;
        }

        @Override
        public void setEditMode(EditMode value) {
            editModes.add(value);
        }

        @Override
        public boolean showEmbeddedDiff(boolean outsideProject, String outsideWarning,
                                        JToolBar toolbar, Component diffComponent,
                                        FileDiffPermissionPanel permPanel, Runnable onTabClose) {
            lastEmbedCalls++;
            lastEmbed = new EmbeddedCall(outsideProject, outsideWarning, toolbar, diffComponent,
                    permPanel, onTabClose);
            return embedResult;
        }

        @Override
        public void hideEmbeddedDiff() {
            hideEmbeddedCalls++;
        }

        @Override
        public void requestActive() {
            requestActiveCalls++;
        }
    }

