    runTest(() -> {
        Path file = writeFile("Deferred.java", "old", "new");
        AtomicInteger closes = new AtomicInteger();
        CountDownLatch edtReleased = new CountDownLatch(1);
        try {
            // Occupy the EDT so the deferred body cannot run until we release it.
            SwingUtilities.invokeLater(() -> {
                try {
                    edtReleased.await(10, TimeUnit.SECONDS);
                } catch (InterruptedException ex) {
                    Thread.currentThread().interrupt();
                }
            });

            TestLookup.install(windowManager, preferences); // no Diff service: the fallback is the observable effect
            FileDiffOpener.open(file.toString(), "old", "new", "Deferred diff", null,
                    () -> { }, reason -> { }, () -> { }, closes::incrementAndGet);

            assertEquals(0, closes.get(), "onClose must not run on the calling thread");
            assertTrue(windowManager.registry.opened.isEmpty(),
                    "no window may be opened before the EDT ran the deferred body");

            edtReleased.countDown();
            flushEdt();
            flushEdt();

            assertEquals(1, closes.get());
            assertTrue(windowManager.registry.opened.isEmpty());
        } catch (Exception ex) {
            throw new AssertionError(ex);
        }
    });
